	xlog("rest\_post() failed with $var(rc), user=$fU\\n");
	send\_reply(500, "Server Internal Error 1");
	exit;
}

if ($var(rcode) != 200) {
	xlog("rest\_post() rcode=$var(rcode), user=$fU\\n");
	send\_reply(500, "Server Internal Error 2");
	exit;
}
